/* Son Son II sound on the Genesis.
 *
 * The native sequencer (ss2_sound_seq.c, a rebuild of the PCE driver) emits
 * the original HuC6280 PSG register writes.  This file keeps them in a
 * virtual PSG (6 channels: period, control/volume, balance, noise, waveform)
 * and once per frame renders that state:
 *
 *   PCE channel c (tone)  -> YM2612 FM channel c, algorithm 7: four sine
 *                            carriers fitted to the channel's 32-sample wave
 *                            (ss2_snd_patch, generated by extract.py).
 *                            Volume/balance/main volume -> carrier TL;
 *                            pan L/R on when that side's balance is nonzero.
 *   PCE channel 4/5 noise -> SN76489 white noise clocked by tone channel 3,
 *                            the louder of the two when both are in use.
 *
 * Pitch: PCE f = 3579545 / (32 * period); YM fnum<<block = K / period.
 * Contract: docs/ss2/SOUND.md; API: inc/ss2_sound.h.
 */
#include "ss2_sound.h"
#include "ss2_sound_seq.h"
#include "ss2_sound_data.h"

/* K = (3579545/32) * 2^21 / (7670453/144) = 4404020 (NTSC), 4444559 with the
 * PAL YM clock 7600489: the fnum tables' constants (gen_fnum.py) */

typedef struct
{
    u16 per;        /* regs 2/3, 12-bit period */
    u8 ctrl;        /* reg 4: on, DDA, volume */
    u8 bal;         /* reg 5 */
    u8 noise;       /* reg 7 (ch 4/5) */
    u8 patch;       /* waveform -> ss2_snd_patch index */
} VPsg;

typedef struct
{
    u16 freq;       /* last block|fnum written, 0xFFFF = none */
    u8 att;         /* last TL offset */
    u8 pan;
    u8 patch;
    u8 keyed;
    u16 akey;           /* volume | balance << 8 the attenuation is for */
    u8 amain, aval;     /* ... and main volume; the attenuation */
} FmCache;

static VPsg vp[6];
static u8 vsel, vmain;
static FmCache fc[6];
static u8 noise_on, noise_att;
static u16 noise_n;
static u8 ready, pal_phase;
extern const u16 ss2_fnum_ntsc[4096], ss2_fnum_pal[4096];
static const u16 *fnum_tab = ss2_fnum_ntsc;

static const u8 op_off[4] = { 0, 4, 8, 12 };

/* ---- sequencer hooks ---------------------------------------------------- */
void ss2_snd_psg_write(u8 reg, u8 val)
{
    VPsg *v;
    if (reg == 0) { vsel = val & 7; return; }
    if (reg == 1) { vmain = val; return; }
    if (vsel >= 6) return;
    v = &vp[vsel];
    switch (reg)
    {
        case 2: v->per = (u16)((v->per & 0x0F00) | val); break;
        case 3: v->per = (u16)((v->per & 0x00FF) | ((val & 0x0F) << 8)); break;
        case 4: v->ctrl = val; break;
        case 5: v->bal = val; break;
        case 7: v->noise = val; break;
        default: break;     /* 6 = wave data (identified by ss2_snd_psg_wave), 8/9 LFO off */
    }
}

void ss2_snd_psg_wave(u16 src)
{
    static u16 last_src = 0xFFFF;
    static u8 last_patch;
    u16 i;
    if (vsel >= 6) return;
    if (src == last_src) { vp[vsel].patch = last_patch; return; }
    for (i = 0; i < ss2_snd_patch_count; i++)
        if (ss2_snd_wave_src[i] == src)
        {
            vp[vsel].patch = (u8)i;
            last_src = src;
            last_patch = (u8)i;
            return;
        }
}

/* ---- YM2612 output -------------------------------------------------------
 * Per-frame register writes are queued and handed to a small Z80 program
 * that performs them with its own busy-flag waits, so the 68000 never spins
 * on the YM. Protocol (Z80 RAM): $1000 = entry count (0 = idle), $1001+ =
 * entries (part offset 0/2, register, value). The Z80 clears $1000 when done.
 *
 *   0000 DI / LD SP,$2000
 *   0004 loop: LD A,($1000) / OR A / JR Z,loop / LD B,A / LD HL,$1001
 *   000E next: LD A,(HL) / INC HL / LD E,A / LD D,$40
 *   0013 busy: LD A,($4000) / RLA / JR C,busy
 *   0019 LD A,(HL) / INC HL / LD (DE),A / INC DE / LD A,(HL) / INC HL
 *   001F LD (DE),A / DJNZ next / XOR A / LD ($1000),A / JR loop
 */
static const u8 ym_z80[] = {
    0xF3, 0x31, 0x00, 0x20,
    0x3A, 0x00, 0x10, 0xB7, 0x28, 0xFA, 0x47, 0x21, 0x01, 0x10,
    0x7E, 0x23, 0x5F, 0x16, 0x40,
    0x3A, 0x00, 0x40, 0x17, 0x38, 0xFA,
    0x7E, 0x23, 0x12, 0x13, 0x7E, 0x23,
    0x12, 0x10, 0xEC, 0xAF, 0x32, 0x00, 0x10, 0x18, 0xDC };

#define YMQ_MAX 120
static vu8 *ymq_p;              /* next free entry in Z80 RAM ($1001+)     */
static u8 ymq_n;
static u8 ymq_on;               /* 1: queue for the Z80; 0: direct (bus held) */

static inline __attribute__((always_inline)) void ym_out(u8 part, u8 reg, u8 val)
{
    if (!ymq_on) { YM2612_writeReg(part, reg, val); return; }
    if (ymq_n >= YMQ_MAX) return;
    ymq_p[0] = (u8)(part << 1);
    ymq_p[1] = reg;
    ymq_p[2] = val;
    ymq_p += 3;
    ymq_n++;
}

/* Take the Z80 bus for the frame's register list; the previous list is
 * normally long finished (a frame holds ~16 ms, a full list ~3 ms). */
static void ymq_begin(void)
{
    vu8 *z = (vu8 *) Z80_RAM;
    for (;;)
    {
        /* VInt can flush a completed picture while sound is prepared.
         * Do not let it observe a request before the Z80 acknowledges it:
         * its DMA helper must see our ownership and leave the bus held. */
        u16 mask = SYS_getAndSetInterruptMaskLevel(7);
        Z80_requestBus(TRUE);
        SYS_setInterruptMaskLevel(mask);
        if (!z[0x1000]) break;
        Z80_releaseBus();
    }
    ymq_p = z + 0x1001;
    ymq_n = 0;
    ymq_on = 1;
}

static void ymq_end(void)
{
    vu8 *z = (vu8 *) Z80_RAM;
    ymq_on = 0;
    z[0x1000] = ymq_n;          /* publish last */
    Z80_releaseBus();
}

/* Load the YM write player. SGDK's Z80_upload is not used: the GCC 16
 * build of libmd compiles its byte copy as move.b (a0)+,(0,a0,d0.l), which
 * stores every byte one address too high on the 68000. The empty asm keeps
 * each load and store a separate instruction. */
static void load_ym_z80(void)
{
    vu8 *z = (vu8 *) Z80_RAM;
    u16 i;
    Z80_loadDriver(Z80_DRIVER_NULL, TRUE);      /* SGDK bookkeeping: a known driver */
    SYS_disableInts();
    Z80_requestBus(TRUE);
    for (i = 0; i < 0x2000; i++) z[i] = 0;
    for (i = 0; i < sizeof(ym_z80); i++)
    {
        u8 b = ym_z80[i];
        __asm__ volatile ("" : "+d" (b));
        z[i] = b;
    }
    Z80_startReset();
    Z80_releaseBus();
    for (i = 0; i < 400; i++) __asm__ volatile ("nop");
    Z80_endReset();
    SYS_enableInts();
}

/* channel ch: part ch / 3, register offset ch % 3 (no division) */
static const u8 ym_part[6] = { 0, 0, 0, 1, 1, 1 };
static const u8 ym_choff[6] = { 0, 1, 2, 0, 1, 2 };

static inline __attribute__((always_inline)) void ym(u8 ch, u8 reg, u8 val)
{
    ym_out(ym_part[ch], (u8)(reg + ym_choff[ch]), val);
}

static void ym_key(u8 ch, u8 on)
{
    ym_out(0, 0x28, (u8)((on ? 0xF0 : 0x00) | (ym_part[ch] << 2) | ym_choff[ch]));
}

static void ym_voice_init(u8 ch)
{
    u8 o;
    for (o = 0; o < 4; o++)
    {
        ym(ch, (u8)(0x30 + op_off[o]), 0x01);   /* DT 0, MUL 1 */
        ym(ch, (u8)(0x40 + op_off[o]), 0x7F);   /* silent */
        ym(ch, (u8)(0x50 + op_off[o]), 0x1F);   /* AR 31 */
        ym(ch, (u8)(0x60 + op_off[o]), 0x00);   /* D1R 0, AM off */
        ym(ch, (u8)(0x70 + op_off[o]), 0x00);   /* D2R 0 */
        ym(ch, (u8)(0x80 + op_off[o]), 0x0F);   /* SL 0, RR 15 */
        ym(ch, (u8)(0x90 + op_off[o]), 0x00);   /* SSG-EG off */
    }
    ym(ch, 0xB0, 0x07);                         /* algorithm 7, FB 0 */
    ym(ch, 0xB4, 0xC0);
    ym_key(ch, 0);
    fc[ch].freq = 0xFFFF; fc[ch].att = 0xFF; fc[ch].pan = 0xC0;
    fc[ch].patch = 0xFF; fc[ch].keyed = 0;
    fc[ch].akey = 0xFFFF;
}

static u8 max_nib(u8 b)
{
    u8 l = b >> 4, r = b & 15;
    return l > r ? l : r;
}

/* attenuation in 0.75 dB TL units: volume 1.5 dB/step, balance and main
 * volume 3 dB/step (HuC6280 PSG); 0xFF = silent */
static u8 pce_att(const VPsg *v)
{
    u8 vol = v->ctrl & 0x1F, side = max_nib(v->bal), mainv = max_nib(vmain);
    u16 a;
    if (!vol || !side || !mainv) return 0xFF;
    a = (u16)((31 - vol) * 2 + (15 - side) * 4 + (15 - mainv) * 4);
    return a > 126 ? 126 : (u8)a;
}

static void render_fm(u8 ch)
{
    const VPsg *v = &vp[ch];
    FmCache *c = &fc[ch];
    u8 noise = (ch >= 4) && (v->noise & 0x80);
    u16 akey = (u16)((v->ctrl & 0x1F) | (v->bal << 8));
    u8 att;
    /* pce_att() of unchanged inputs (volume envelopes are often static) */
    if (akey != c->akey || vmain != c->amain)
    {
        c->akey = akey; c->amain = vmain; c->aval = pce_att(v);
    }
    att = c->aval;
    u8 on = (v->ctrl & 0x80) && !(v->ctrl & 0x40) && !noise && att != 0xFF && v->per;
    u8 o;
    if (!on)
    {
        if (c->keyed) { ym_key(ch, 0); c->keyed = 0; }
        return;
    }
    if (c->patch != v->patch)
    {
        const Ss2FmPatch *p = &ss2_snd_patch[v->patch];
        for (o = 0; o < 4; o++) ym(ch, (u8)(0x30 + op_off[o]), p->mul[o]);
        c->patch = v->patch;
        c->att = 0xFF;
    }
    if (c->att != att)
    {
        const Ss2FmPatch *p = &ss2_snd_patch[c->patch];
        for (o = 0; o < 4; o++)
        {
            /* Algorithm 7: all four operators are carriers. Recover the
             * extractor's 8-TL (6 dB) mix reserve without changing their
             * relative levels. Preserve unused/silent operators below. */
            u16 t = (u16)(p->tl[o] + att);
            t = t >= 8 ? t - 8 : 0;
            ym(ch, (u8)(0x40 + op_off[o]), (u8)(p->tl[o] >= 127 || t > 127 ? 127 : t));
        }
        c->att = att;
    }
    {
        u8 pan = (u8)(((v->bal & 0xF0) ? 0x80 : 0) | ((v->bal & 0x0F) ? 0x40 : 0));
        if (pan != c->pan) { ym(ch, 0xB4, pan); c->pan = pan; }
    }
    {
        u16 w;
        /* block|fnum for the 12-bit period: K / per halved into a block,
         * precomputed (src/ss2_sound_fnum.c, tools/ss2/sound/gen_fnum.py) */
        w = fnum_tab[v->per];
        if (w != c->freq)
        {
            ym(ch, 0xA4, (u8)(w >> 8));
            ym(ch, 0xA0, (u8)w);
            c->freq = w;
        }
    }
    if (!c->keyed) { ym_key(ch, 1); c->keyed = 1; }
}

static void render_noise(void)
{
    u8 ch, best = 0xFF, batt = 0xFF;
    for (ch = 4; ch < 6; ch++)
    {
        const VPsg *v = &vp[ch];
        u8 a;
        if (!(v->noise & 0x80) || !(v->ctrl & 0x80) || (v->ctrl & 0x40)) continue;
        a = pce_att(v);
        if (a != 0xFF && (best == 0xFF || a <= batt)) { best = ch; batt = a; }
    }
    if (best == 0xFF)
    {
        if (noise_on) { PSG_setEnvelope(3, PSG_ENVELOPE_MIN); noise_on = 0; }
        return;
    }
    {
        u16 k = (u16)((vp[best].noise & 0x1F) ^ 0x1F);
        u16 n = k ? (u16)(k * 2) : 1;           /* shift rate 3.58 MHz/(64k) */
        u8 sn = (u8)((batt * 3) >> 3);          /* 0.75 dB -> 2 dB steps */
        if (sn > 15) sn = 15;
        if (!noise_on)
        {
            PSG_setEnvelope(2, PSG_ENVELOPE_MIN);
            PSG_setNoise(PSG_NOISE_TYPE_WHITE, PSG_NOISE_FREQ_TONE3);
            noise_on = 1; noise_n = 0xFFFF; noise_att = 0xFF;
        }
        if (n != noise_n) { PSG_setTone(2, n); noise_n = n; }
        if (sn != noise_att) { PSG_setEnvelope(3, sn); noise_att = sn; }
    }
}

static void render(void)
{
    u8 ch;
    ymq_begin();
    for (ch = 0; ch < 6; ch++) render_fm(ch);
    ymq_end();
    render_noise();
}

static void chips_silent(void)
{
    u8 ch;
    bool taken = Z80_getAndRequestBus(TRUE);
    YM2612_writeReg(0, 0x22, 0x00);             /* LFO off */
    YM2612_writeReg(0, 0x27, 0x00);             /* ch3 normal mode, timers off */
    YM2612_writeReg(0, 0x2B, 0x00);             /* DAC off: FM6 is a music voice */
    for (ch = 0; ch < 6; ch++) ym_voice_init(ch);
    if (!taken) Z80_releaseBus();
    for (ch = 0; ch < 4; ch++) PSG_setEnvelope(ch, PSG_ENVELOPE_MIN);
    noise_on = 0;
}

/* ---- public API ------------------------------------------------------------ */
void ss2_sound_init(void)
{
    u8 i;
    ready = 0;
    ymq_on = 0;
    load_ym_z80();
    for (i = 0; i < 6; i++)
    {
        vp[i].per = 0; vp[i].ctrl = 0; vp[i].bal = 0; vp[i].noise = 0; vp[i].patch = 0;
    }
    vsel = 0; vmain = 0;
    chips_silent();
    ss2_snd_seq_reset();
    fnum_tab = SYS_isPAL() ? ss2_fnum_pal : ss2_fnum_ntsc;
    pal_phase = 0;
    ready = 1;
}

void ss2_sound_request(u8 id)
{
    if (ready) ss2_snd_seq_queue(id);
}

void ss2_sound_set_hold(u8 v)
{
    ss2_snd_seq_set_hold(v);
}

#if defined(SS2_PROF) || defined(SS2_TPROF)
void ss2_prof_mark(u8 sec);
#define PROF(n) ss2_prof_mark(n)
#else
#define PROF(n)
#endif

void ss2_sound_tick(void)
{
    if (!ready) return;
    PROF(4);
    ss2_snd_seq_frame();
    if (SYS_isPAL() && ++pal_phase >= 5)
    {                                           /* 50 Hz: 6 source frames per 5 */
        pal_phase = 0;
        ss2_snd_seq_frame();
    }
    PROF(5);
    render();
    PROF(6);
}

void ss2_sound_shutdown(void)
{
    ready = 0;
    ymq_on = 0;
    chips_silent();
    ss2_snd_seq_reset();
    /* leave the chips as SonSon's driver expects: NULL driver, bus held */
    Z80_loadDriver(Z80_DRIVER_NULL, TRUE);
    Z80_requestBus(TRUE);
}
